mapper.select:
/*selectSellerMpClDlvryCarPop_Count*/

		SELECT
		    COUNT(*) AS CNT 
		FROM
		    ICOMCOD2 /* 회사별 코드관리 */
		WHERE 1=1
		AND TYPE = 'CA01'
		AND CODE = #{st_car_code}
		AND COMPANY_CODE = #{st_com_code}

mapper.update:
/*insertSellerMpClDlvryCarPop*/

		INSERT INTO ICOMCOD2 /* 회사별 코드관리 */
		(
		    TYPE
		  , CODE 
		  , COMPANY_CODE 
		  , TEXT1 
		  , TEXT2
		  , TEXT3 
		  , FLAG 
		  , ADD_DATE 
		)
		VALUES
		(
		    'CA01'
		  , #{st_car_code}
		  , #{st_com_code}
		  , #{st_car_number}
		  , #{st_user_name}
		  , #{st_phone_num}
		  , 'Y'
		  , TO_CHAR(SYSDATE, 'YYYYMMDD')
		)

/*updateSellerMpClDlvryCarPop*/

		UPDATE 
		    ICOMCOD2 /* 회사별 코드관리 */
		SET TEXT1 = #{st_car_number}
		  , TEXT2 = #{st_user_name}
		  , TEXT3 = #{st_phone_num}
		WHERE 1=1
		AND TYPE  = 'CA01'
		AND CODE  = #{st_car_code}
		AND COMPANY_CODE = #{st_com_code}

/*deleteSellerMpClDlvryCarPop*/

		DELETE 
		    ICOMCOD2 /* 회사별 코드관리 */
		WHERE 1=1
		AND TYPE  = 'CA01'
		AND CODE  = #{st_car_code}
		AND COMPANY_CODE = #{st_com_code}
